graphql.query:
query IntrospectFields {
  __schema {
    queryType {
      fields {
        name
        description
      }
    }
  }
}

query IntrospectMutations {
  __schema {
    mutationType {
      fields {
        name
        description
      }
    }
  }
}

query MyOrgs {
  platformTenantCollection {
    edges {
      node {
        id
        name
        slug
        billingTier
      }
    }
  }
}

query MyPortfolios {
  portfoliosCollection {
    edges {
      node {
        id
        name
        description
        orgId
      }
    }
  }
}

query Sites {
  sitesCollection(orderBy: {name: AscNullsLast}) {
    edges {
      node {
        id
        name
        slug
        type
        status
        city
        state
        addressLine1
        sqFt
      }
    }
  }
}

query SitesHierarchy {
  portfoliosCollection {
    edges {
      node {
        id
        name
        sitesCollection(orderBy: {name: AscNullsLast}) {
          edges {
            node {
              id
              name
              slug
              city
              type
              buildingsCollection {
                edges {
                  node {
                    id
                    name
                    floorsCount
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

mutation SearchSites($q: String!, $orgId: UUID) {
  searchSites(searchQuery: $q, pOrgId: $orgId, limitCount: 10) {
    edges {
      node {
        id
        name
        addressLine1
        city
      }
    }
  }
}

mutation CreateOrg($name: String!, $slug: String!) {
  createTenant(pName: $name, pSlug: $slug) {
    id
    name
    slug
  }
}

query Assets($siteId: UUID!) {
  assetsCollection(filter: {siteId: {eq: $siteId}}) {
    edges {
      node {
        id
        name
        status
        criticality
        qrCode
        manufacturer
      }
    }
  }
}

query WOs($siteId: UUID!) {
  workOrdersCollection(filter: {siteId: {eq: $siteId}, status: {neq: completed}}, orderBy: {priority: DescNullsLast}, first: 20) {
    edges {
      node {
        id
        title
        status
        priority
        slaDueAt
        completedAt
      }
    }
  }
}

mutation CompleteWO($id: UUID!) {
  completeWorkOrder(pWorkOrderId: $id) {
    id
    status
    completedAt
  }
}

query Checklists {
  checklistsCollection {
    edges {
      node {
        id
        name
        category
        checklistItemsCollection {
          edges {
            node {
              label
              itemType
              isRequired
            }
          }
        }
      }
    }
  }
}

mutation CreateInsp($siteId: UUID!, $checklistId: UUID!, $assetId: UUID!) {
  createInspectionFromChecklist(pSiteId: $siteId, pChecklistId: $checklistId, pAssetId: $assetId, pTitle: "Monthly HVAC") {
    id
    title
    status
  }
}

mutation CompleteInsp($id: UUID!) {
  completeInspection(pInspectionId: $id) {
    id
    status
    score
  }
}

query LowStock($siteId: UUID!) {
  inventoryStockCollection(filter: {siteId: {eq: $siteId}}) {
    edges {
      node {
        quantity
        inventoryItem {
          name
          sku
          minStockLevel
        }
      }
    }
  }
}

query Ann($siteId: UUID!) {
  announcementsCollection(filter: {siteId: {eq: $siteId}, isPublished: {eq: true}}, orderBy: {publishAt: DescNullsLast}) {
    edges {
      node {
        id
        title
        body
        priority
        audience
        publishAt
      }
    }
  }
}

query Amenities($siteId: UUID!) {
  amenitiesCollection(filter: {siteId: {eq: $siteId}, isBookable: {eq: true}}) {
    edges {
      node {
        id
        name
        category
        capacity
        hourlyRate
      }
    }
  }
}

mutation Check($spaceId: UUID!, $start: Datetime!, $end: Datetime!) {
  checkReservationConflict(pSpaceId: $spaceId, pStart: $start, pEnd: $end)
}

mutation Book($siteId: UUID!, $spaceId: UUID!, $start: Datetime!, $end: Datetime!) {
  createReservation(pSiteId: $siteId, pSpaceId: $spaceId, pStart: $start, pEnd: $end, pTitle: "Team Meeting", pAttendees: 8) {
    id
    title
    startTime
    endTime
    status
  }
}

query SR($siteId: UUID!) {
  serviceRequestsCollection(filter: {siteId: {eq: $siteId}}, orderBy: {createdAt: DescNullsLast}) {
    edges {
      node {
        id
