}

mutation Register($siteId: UUID!, $name: String!, $email: String!) {
  registerVisitor(pSiteId: $siteId, pName: $name, pEmail: $email, pPurpose: "Meeting") {
    id
    qrCode
    status
  }
}

mutation CheckIn($token: String!) {
  checkInVisitor(pToken: $token) {
